<style>
    :root{--accent-color:#00ff9d;--cyan:#38d9ff;--gold:#ffd166;--panel:rgba(3,18,24,.9)}
    *{box-sizing:border-box}
    body{min-height:100vh;margin:0;overflow-x:hidden;color:#eefcf8;font-family:Roboto,sans-serif;background:url('{{ asset("Imagenes/Pantalla_Inicio.jpg") }}') center/cover fixed no-repeat}
    body::before{content:'';position:fixed;inset:0;z-index:-1;background:linear-gradient(135deg,rgba(1,10,15,.88),rgba(0,25,30,.76))}
    .navbar-custom{background:rgba(0,0,0,.8)!important;border-bottom:3px solid var(--accent-color)}
    .game-title{margin:0 auto;color:var(--accent-color);font:1.5rem 'Press Start 2P',cursive;text-shadow:3px 3px 0 #000}
    .btn-home{border:2px solid #fff;border-radius:50px;background:transparent;color:#fff!important;transition:.2s}
    .btn-home:hover{background:#ffffff24;transform:scale(1.05)}
    .player-name-display{display:flex;align-items:center;padding:8px 15px;border:2px solid #fff;border-radius:50px;background:#ffffff18;color:#fff}
    .intro-shell{width:min(1080px,calc(100% - 32px));margin:32px auto 60px;padding:clamp(20px,4vw,44px);border:1px solid #36e8ba80;border-radius:24px;background:var(--panel);box-shadow:0 24px 70px #0008;backdrop-filter:blur(12px)}
    .intro-hero{display:grid;grid-template-columns:auto 1fr;gap:22px;align-items:center;padding-bottom:28px;border-bottom:1px solid #4f8b815c}
    .intro-icon{width:82px;height:82px;display:grid;place-items:center;border:2px solid var(--accent-color);border-radius:22px;background:#00ff9d18;color:var(--accent-color);font-size:35px;box-shadow:0 0 28px #00ff9d22}
    .eyebrow{margin:0 0 7px;color:var(--gold);font-size:.82rem;font-weight:900;letter-spacing:.16em;text-transform:uppercase}
    h1{margin:0;color:#fff;font-family:'Press Start 2P',cursive;font-size:clamp(1.35rem,3vw,2rem);line-height:1.45}
    .hero-copy{margin:12px 0 0;color:#bdd2ce;font-size:1.08rem;line-height:1.7}
    .intro-section{margin-top:30px}.intro-section h2{margin:0 0 15px;color:var(--accent-color);font-size:1.45rem}.intro-section>p{color:#d6e5e2;font-size:1.04rem;line-height:1.75}
    .concept-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.concept-card{height:100%;padding:20px;border:1px solid #47766e;border-radius:16px;background:#0b2a31cc}.concept-card i{margin-bottom:12px;color:var(--gold);font-size:1.55rem}.concept-card h3{margin:0 0 8px;font-size:1.05rem}.concept-card p{margin:0;color:#b9cfcb;line-height:1.55}
    .example-flow{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:12px;align-items:stretch}.flow-card{display:grid;place-items:center;min-height:116px;padding:17px;border:1px solid #2bbf98;border-radius:15px;background:#05272a;text-align:center}.flow-card strong{display:block;color:#fff}.flow-card span{display:block;margin-top:5px;color:#a9c7c1;font-size:.92rem}.flow-arrow{display:grid;place-items:center;color:var(--accent-color);font-size:1.4rem}
    .note-box{padding:18px 20px;border-left:4px solid var(--gold);border-radius:0 14px 14px 0;background:#ffd16615;color:#f8edcf;line-height:1.65}
    .task-list{display:grid;grid-template-columns:repeat(2,1fr);gap:13px;padding:0;list-style:none}.task-list li{display:flex;gap:12px;padding:17px;border:1px solid #345f5b;border-radius:14px;background:#09232a}.task-list i{margin-top:3px;color:var(--accent-color)}.task-list strong{display:block;margin-bottom:4px}.task-list span{color:#b8ceca;line-height:1.5}
    .people-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.person-card{overflow:hidden;border:1px solid #47766e;border-radius:18px;background:#09232a;box-shadow:0 12px 28px #0005}.person-photo{width:100%;height:250px;display:block;object-fit:cover;object-position:center}.person-content{padding:20px}.person-tag{display:inline-flex;align-items:center;gap:7px;margin-bottom:10px;padding:5px 9px;border:1px solid #ffd16669;border-radius:999px;background:#ffd16614;color:var(--gold);font-size:.76rem;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.person-card h3{margin:0 0 9px;color:#fff;font-size:1.22rem}.person-card p{margin:0;color:#c2d7d3;line-height:1.62}.photo-credit{padding:9px 20px 15px;color:#86a7a1;font-size:.72rem;line-height:1.45}.photo-credit a,.source-list a{color:#70e6c8}.source-list{display:grid;gap:9px;margin:0;padding-left:20px;color:#bdd2ce;line-height:1.55}
    .future-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.future-card{display:flex;gap:15px;padding:20px;border:1px solid #3d7169;border-radius:16px;background:#08252bcc}.future-card>i{width:42px;height:42px;flex:0 0 42px;display:grid;place-items:center;border-radius:12px;background:#00ff9d18;color:var(--accent-color);font-size:1.2rem}.future-card h3{margin:0 0 7px;color:#fff;font-size:1.05rem}.future-card p{margin:0;color:#b9cfcb;line-height:1.55}.skill-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.skill-pill{padding:17px;border:1px solid #38615d;border-radius:14px;background:#061f26;text-align:center}.skill-pill i{display:block;margin-bottom:9px;color:var(--gold);font-size:1.35rem}.skill-pill strong{display:block;color:#fff}.skill-pill span{display:block;margin-top:5px;color:#adc6c1;font-size:.9rem;line-height:1.45}
    .closing{margin-top:30px;padding:22px;border:1px solid #00ff9d7d;border-radius:17px;background:linear-gradient(120deg,#00ff9d14,#38d9ff0d);text-align:center}.closing strong{color:var(--accent-color);font-size:1.15rem}.closing p{margin:8px 0 0;color:#d4e8e4}
    @media(max-width:900px){.people-grid{grid-template-columns:1fr}.person-card{display:grid;grid-template-columns:220px 1fr}.person-photo{height:100%;min-height:260px}.photo-credit{grid-column:2}}
    @media(max-width:800px){.intro-hero{grid-template-columns:1fr;text-align:center}.intro-icon{margin:auto}.concept-grid,.future-grid,.skill-strip{grid-template-columns:1fr}.example-flow{grid-template-columns:1fr}.flow-arrow{transform:rotate(90deg)}.task-list{grid-template-columns:1fr}.game-title{font-size:1rem}}
    @media(max-width:560px){.person-card{display:block}.person-photo{height:260px}.photo-credit{display:block}}
</style>
